package com.takehome.savings.api.dto;

import io.swagger.v3.oas.annotations.media.Schema;

/**
 * Body of a successful create. Deliberately minimal: it carries the freshly
 * generated account number and nothing else.
 *
 * <p>The autogenerated {@code id} is NOT a field here - that is a hard
 * requirement for the create response. The opaque identifier travels once, in
 * the {@code Location} header, so the caller can address the resource
 * immediately while the response body discloses as little as a bank-grade API
 * should.
 */
@Schema(description = "Minimal create response - the generated account number only, per requirement.")
public record CreateAccountResponse(
        @Schema(description = "12-digit account number generated by the API, Luhn check digit last",
                example = "453008838865", requiredMode = Schema.RequiredMode.REQUIRED)
        String accountNumber) {
}
